  function closePeriod(){var from=$('#bs-report-from').value,to=$('#bs-report-to').value;if(!from||!to)throw new Error('Choose a period first');ctx.modal({title:'Close financial period',body:'<p>From '+esc(from)+' through '+esc(to)+'. The server must reconcile journal totals and control accounts before locking. Closed periods block retroactive postings.</p><div class="field"><label>Required close review notes</label><textarea class="input" id="bs-close-notes" required></textarea></div>',confirmText:'Reconcile and lock period',onConfirm:async function(host){var reason=$('#bs-close-notes',host).value.trim();if(!reason)throw new Error('Review notes are required');await ctx.api('/api/business/admin/finance/close',{method:'POST',body:{from:from,to:to,reason:reason}});ctx.toast('Period reconciled and locked','success');return true;}});}
  function install(options){ctx=options;document.addEventListener('change',function(e){if(e.target.id==='bs-admin-venue'){venueId=Number(e.target.value);queueId=null;load();}});document.addEventListener('click',function(e){var tab=e.target.closest('[data-bsa-view]');if(tab){view=tab.dataset.bsaView;load();return;}var b=e.target.closest('[data-bsa-action]');if(!b)return;b.disabled=true;Promise.resolve(action(b.dataset.bsaAction,b.dataset.bsaId,b)).catch(function(err){ctx.toast(err.message,'error');}).finally(function(){if(b.isConnected)b.disabled=false;});});document.addEventListener('input',function(e){if(e.target.matches('[data-bs-field="kind"]'))updateBenefitField(true);if(e.target.id==='bs-admin-search'){var needle=e.target.value.trim().toLowerCase(),filtered=records.filter(function(r){return Object.values(r).some(function(v){return typeof v!=='object'&&String(v).toLowerCase().includes(needle);});});$('#bs-admin-records').innerHTML=table(filtered,columns[view] || []);}});window.addEventListener('pikol-business-change',function(){if(!$('#page-business').classList.contains('hidden')){if(view==='queue'&&queueId)loadQueue(queueId);else load();}});}
  function venueQrHtml(data){var event=records.find(function(r){return Number(r.id)===queueId;}) || {},venueId=Number(data.event && data.event.venue_id || event.venue_id);if(!venueId)return '<p class="bs-note">Configure the event venue before displaying a venue check-in QR.</p>';var brand=ctx.getBranding?ctx.getBranding():{},url;try{url=new URL(brand.website || location.href);}catch(_){url=new URL(location.href);}if(!/^https?:$/.test(url.protocol)||url.username||url.password)url=new URL(location.href);url.pathname=url.pathname.replace(/[^/]*$/,'index.html');url.search='';url.hash='';url.searchParams.set('view','events');url.searchParams.set('tab','open-play');url.searchParams.set('venue',String(venueId));var svg='';if(window.qrcodegen){var qr=qrcodegen.QrCode.encodeText(url.href,qrcodegen.QrCode.Ecc.MEDIUM),n=qr.size,path='';for(var y=0;y<n;y++)for(var x=0;x<n;x++)if(qr.getModule(x,y))path+='M'+(x+4)+','+(y+4)+'h1v1h-1z';svg='<div class="bs-qr"><svg role="img" aria-label="Permanent venue check-in QR" viewBox="0 0 '+(n+8)+' '+(n+8)+'"><rect width="100%" height="100%" fill="white"/><path d="'+path+'" fill="#102215"/></svg></div>';}return '<details class="bs-card"><summary>Permanent venue check-in QR</summary>'+svg+'<input class="input" readonly aria-label="Venue check-in link" value="'+esc(url.href)+'"><p class="bs-note">Venue '+venueId+'. Reuse this venue link for live sessions. The server checks the venue, active event, registration, payment and signed-in identity.</p></details>';}
  async function configureQueue(){var current=await ctx.api('/api/business/admin/queue/'+queueId),s=current.settings || {};ctx.modal({title:'Open Play rotation policy',body:'<div class="bs-fields"><label class="field"><span class="label">Rotation policy</span><select class="select" id="bs-queue-mode">'+[['fifo_four_off','FIFO · four on / four off'],['winner_stays','Winner stays with a consecutive game cap'],['two_on','Two on / two off with a consecutive game cap']].map(function(v){return '<option value="'+v[0]+'"'+(s.mode===v[0]?' selected':'')+'>'+v[1]+'</option>';}).join('')+'</select></label><label class="field"><span class="label">Pairing</span><select class="select" id="bs-queue-pairing"><option value="fixed"'+(s.pairing==='fixed'?' selected':'')+'>Fixed FIFO pairs</option><option value="random"'+(s.pairing==='random'?' selected':'')+'>Random next-four pairs</option></select></label><label class="field"><span class="label">Game duration (minutes)</span><input class="input" id="bs-queue-minutes" type="number" min="1" max="120" value="'+esc(s.game_minutes||15)+'"></label><label class="field"><span class="label">Maximum consecutive games</span><input class="input" id="bs-queue-cap" type="number" min="1" max="5" value="'+esc(s.maxConsecutiveGames||2)+'"></label><label class="field"><span class="label">Post-game rest (minutes)</span><input class="input" id="bs-queue-rest" type="number" min="0" max="60" value="'+esc(s.restMinutes||0)+'"></label><label class="field"><span class="label">Called player no-show grace (0 disables)</span><input class="input" id="bs-queue-no-show" type="number" min="0" max="30" value="'+esc(s.noShowMinutes||0)+'"></label></div><label><input type="checkbox" id="bs-queue-automatic"'+(s.auto_rotation?' checked':'')+'> Automatically rotate at game timer end</label><p class="bs-note">Enable only when staff stop physical play at the scheduled timer end. Winner-stays needs a recorded team winner; a timer without a result safely rotates both teams. Staff must call the next FIFO group before a no-show deadline begins. Pause stops automatic rotation. No membership priority and no competitive RP.</p>',confirmText:'Save queue policy',onConfirm:async function(host){var body={mode:$('#bs-queue-mode',host).value,automatic:$('#bs-queue-automatic',host).checked,pairing:$('#bs-queue-pairing',host).value,gameMinutes:Number($('#bs-queue-minutes',host).value),maxConsecutiveGames:Number($('#bs-queue-cap',host).value),restMinutes:Number($('#bs-queue-rest',host).value),noShowMinutes:Number($('#bs-queue-no-show',host).value)};await ctx.api('/api/business/admin/queue/'+queueId+'/configure',{method:'POST',body:body});await loadQueue(queueId);return true;}});}
  function queueEntryAction(name,id){var call=name==='queue-entry-call',resume=name==='queue-entry-resume';ctx.modal({title:call?'Call the next FIFO player':resume?'Resume after rest':'Rest a waiting player',body:call?'<p>This records a staff call and starts the configured no-show grace. The server requires the next eligible FIFO group.</p>':resume?'<p>The player returns at the queue tail after eligibility checks.</p>':'<label class="field"><span class="label">Rest minutes</span><input class="input" id="bs-queue-player-rest" type="number" min="1" max="60" value="5"></label>',confirmText:'Record queue action',onConfirm:async function(host){await ctx.api('/api/business/admin/queue/entries/'+Number(id)+'/'+(call?'call':'rest'),{method:'POST',body:call?{}:{minutes:resume?0:Number($('#bs-queue-player-rest',host).value)}});await loadQueue(queueId);return true;}});}
  function transferStock(){if(venues.filter(function(v){return v.status==='active';}).length<2)throw new Error('Stock transfers require two active venues');var requestKey=uid();ctx.modal({title:'Transfer stock between club venues',body:'<p>Only unreserved stock may move. Exact inventory carrying value moves between the selected venues.</p><label class="field"><span class="label">Product at this venue</span><select class="select" id="bs-transfer-product">'+inventory.map(function(p){return '<option value="'+p.product_id+'">'+esc(p.sku)+' · '+esc(p.product_name)+' · '+esc(Number(p.quantity)-Number(p.reserved))+' available</option>';}).join('')+'</select></label><label class="field"><span class="label">Destination venue</span><select class="select" id="bs-transfer-venue">'+venues.filter(function(v){return v.status==='active'&&Number(v.id)!==venueId;}).map(function(v){return '<option value="'+v.id+'">'+esc(v.name)+'</option>';}).join('')+'</select></label><label class="field"><span class="label">Quantity physically transferred</span><input class="input" id="bs-transfer-quantity" type="number" min="1" value="1"></label>'+reasonInput(),confirmText:'Record stock transfer',onConfirm:async function(host){var quantity=Number($('#bs-transfer-quantity',host).value);if(!Number.isSafeInteger(quantity)||quantity<1)throw new Error('Choose a positive whole quantity');await ctx.api('/api/business/admin/stock/transfers',{method:'POST',body:{productId:Number($('#bs-transfer-product',host).value),fromVenueId:venueId,toVenueId:Number($('#bs-transfer-venue',host).value),quantity:quantity,requestKey:requestKey,reason:checkedReason(host)}});await load();return true;}});}
  function methodInput(){return '<label class="field"><span class="label">Actual payment or refund method</span><select class="select" id="bs-operation-method"><option value="cash">Cash</option><option value="gcash">GCash</option><option value="maya">Maya</option><option value="other">Other approved method</option></select></label>';}
  function reasonInput(){return '<label class="field"><span class="label">Required approval or review reason</span><textarea class="input" id="bs-operation-reason" required></textarea></label>';}
  function checkedReason(host){var reason=$('#bs-operation-reason',host).value.trim();if(reason.length<3)throw new Error('Enter the approval or review reason');return reason;}
  async function operationalAction(name,id,element){
    if(name==='journal-line-add')return addJournalLine();if(name==='journal-line-remove'){element.closest('[data-bs-journal-line]').remove();return;}
    if(name==='journal-create')return manualJournal();if(name==='journal-reverse')return reverseJournal();
    if(name==='order-return')return returnOrder(id);
    var record=records.find(function(r){return String(r.id)===String(id);}) || {},path,fields='',title;
    if(name==='order-fulfill'){path='store/orders/'+id+'/fulfill';title='Confirm order handover';fields='<p>Order #'+esc(id)+' has verified payment. Confirm the goods were handed to the customer.</p>';}
    if(name==='stock-adjust'){path='stock/adjust';title='Approved stock write-off';fields='<label class="field"><span class="label">Product</span><select class="select" id="bs-operation-product">'+inventory.map(function(p){return '<option value="'+(p.product_id||p.id)+'">'+esc(p.sku)+' · '+esc(p.product_name||p.name)+' · '+esc(Number(p.quantity)-Number(p.reserved))+' available</option>';}).join('')+'</select></label><label class="field"><span class="label">Damaged, expired or lost quantity</span><input class="input" id="bs-operation-quantity" type="number" min="1" value="1"></label><p class="bs-note">Reserved stock cannot be written off. The cost is posted to inventory loss with your reason.</p>';}
    if(name==='asset-maintenance'){path='assets/'+id+'/maintenance';title='Equipment maintenance';fields='<p>'+esc(record.asset_tag)+' · '+esc(record.model)+'</p><label class="field"><span class="label">State after inspection</span><select class="select" id="bs-operation-state"><option value="maintenance">Maintenance</option><option value="available">Available after inspection</option><option value="retired">Retired</option></select></label><label class="field"><span class="label">Current condition</span><input class="input" id="bs-operation-condition" value="'+esc(record.condition_text)+'"></label>';}
    if(name==='rental-assess'){path='rentals/'+id+'/assess';title='Approved equipment charge';fields='<p>Rental #'+esc(id)+'. Deposit '+amount(record.deposit_cents)+'. Charges require an approved rental policy.</p><label class="field"><span class="label">Total assessed damage or overdue charge (₱)</span><input class="input" id="bs-operation-amount" type="number" step="0.01" min="0" value="'+(Number(record.assessed_cents||0)/100).toFixed(2)+'"></label>';}
    if(name==='rental-refund'||name==='coaching-refund'){path=(name==='rental-refund'?'rentals/':'coaching-enrollments/')+id+'/refund';title='Approved unearned payment refund';fields='<p>Refund requires approved policy and an eligible paid service that has not been earned. Confirm the actual refund before recording.</p>'+methodInput()+'<label><input type="checkbox" id="bs-operation-refunded"> I paid the approved refund to the customer</label>';}
    if(name==='session-cancel'){path='coaching-sessions/'+id+'/cancel';title='Cancel training session';fields='<p>'+esc(record.title)+'. Resolve paid enrollments before cancellation. The server releases pending participants and the court hold.</p>';}
    if(name==='referral-reject'){path='referrals/'+id+'/review';title='Referral fraud review';fields='<p>Reject this pending or held attribution only after review. No reward is issued.</p>';}
    if(!path)throw new Error('Operation unavailable');var requestKey=uid();
    ctx.modal({title:title,body:fields+reasonInput(),confirmText:'Record approved action',onConfirm:async function(host){var body={reason:checkedReason(host),requestKey:requestKey,venueId:venueId};if(name==='stock-adjust'){body.productId=Number($('#bs-operation-product',host).value);body.quantity=Number($('#bs-operation-quantity',host).value);if(!Number.isSafeInteger(body.quantity)||body.quantity<1)throw new Error('Choose a positive whole quantity');}if(name==='asset-maintenance'){body.status=$('#bs-operation-state',host).value;body.condition=$('#bs-operation-condition',host).value.trim();}if(name==='rental-assess')body.amountCents=decimalCents($('#bs-operation-amount',host).value);if(name==='rental-refund'||name==='coaching-refund'){if(!$('#bs-operation-refunded',host).checked)throw new Error('Confirm the refund was actually paid');body.method=$('#bs-operation-method',host).value;}await ctx.api('/api/business/admin/'+path,{method:'POST',body:body});ctx.toast('Action recorded and audited','success');await load();return true;}});
  }
  async function returnOrder(id){var order=await ctx.api('/api/business/admin/store/orders/'+Number(id)),available=(order.items||[]).filter(function(i){return Number(i.quantity)>Number(i.returned_quantity||0);});if(!available.length)throw new Error('This order has no remaining returnable items');var requestKey=uid();ctx.modal({title:'Inspect merchandise return',body:'<p>Order #'+esc(id)+'. Select only returned items. The server calculates the exact refund and cost reversal from the original order.</p>'+available.map(function(i){return '<div class="bs-fields bs-cart" data-bs-return-item="'+i.id+'"><label class="field"><span class="label">'+esc(i.name || i.sku || 'Item #'+i.product_id)+' · '+esc(Number(i.quantity)-Number(i.returned_quantity||0))+' returnable</span><input class="input bs-return-quantity" type="number" min="0" max="'+(Number(i.quantity)-Number(i.returned_quantity||0))+'" value="0"></label><label class="field"><span class="label">Fit for resale</span><input class="bs-return-restock" type="checkbox" checked></label></div>';}).join('')+methodInput()+reasonInput()+'<label><input type="checkbox" id="bs-operation-refunded"> I paid the approved refund for the selected items</label>',confirmText:'Record return and refund',onConfirm:async function(host){if(!$('#bs-operation-refunded',host).checked)throw new Error('Confirm the actual refund payment');var items=[];host.querySelectorAll('[data-bs-return-item]').forEach(function(row){var q=Number($('.bs-return-quantity',row).value);if(!Number.isSafeInteger(q)||q<0)throw new Error('Choose whole return quantities');if(q)items.push({itemId:Number(row.dataset.bsReturnItem),quantity:q,restock:$('.bs-return-restock',row).checked});});if(!items.length)throw new Error('Choose returned items');await ctx.api('/api/business/admin/store/orders/'+Number(id)+'/return',{method:'POST',body:{items:items,method:$('#bs-operation-method',host).value,reason:checkedReason(host),requestKey:requestKey}});await load();return true;}});}
  var journalAccounts=[];
  function addJournalLine(){var host=$('#bs-journal-lines');if(!host)return;var row=document.createElement('div');row.className='bs-fields bs-cart';row.setAttribute('data-bs-journal-line','');row.innerHTML='<label class="field"><span class="label">Account</span><select class="select bs-journal-account">'+journalAccounts.map(function(a){return '<option value="'+esc(a.code)+'">'+esc(a.code)+' · '+esc(a.name)+'</option>';}).join('')+'</select></label><label class="field"><span class="label">Debit (₱)</span><input class="input bs-journal-debit" type="number" min="0" step="0.01" value="0"></label><label class="field"><span class="label">Credit (₱)</span><input class="input bs-journal-credit" type="number" min="0" step="0.01" value="0"></label>'+button('journal-line-remove','','Remove line');host.appendChild(row);}
  async function manualJournal(){var chart=await ctx.api('/api/business/admin/finance/trial-balance');journalAccounts=rows(chart.rows);if(!journalAccounts.length)throw new Error('The account chart is unavailable');var sourceId=uid();ctx.modal({title:'Post approved manual journal',body:'<p class="bs-note">Use a documented opening balance, expense, settlement or approved adjustment. Debits and credits must balance exactly. Operational purchase, receipt and refund actions post their own journals.</p><label class="field"><span class="label">Business unit</span><select class="select" id="bs-journal-unit">'+['club','court','tournament','open_play','membership','credit','merchandise','rental','coaching','bundle'].map(function(k){return '<option value="'+k+'">'+esc(k.replace(/_/g,' '))+'</option>';}).join('')+'</select></label><label class="field"><span class="label">Occurred at (Asia/Manila)</span><input class="input" id="bs-journal-date" type="datetime-local" value="'+localTime(new Date().toISOString())+'"></label>'+reasonInput()+'<div id="bs-journal-lines"></div>'+button('journal-line-add','','Add account line')+'<label><input type="checkbox" id="bs-journal-approved"> I verified the supporting document and approve this entry</label>',confirmText:'Post balanced journal',onConfirm:async function(host){if(!$('#bs-journal-approved',host).checked)throw new Error('Confirm supporting documents and approval');var debit=0,credit=0,lines=Array.from(host.querySelectorAll('[data-bs-journal-line]')).map(function(row){var d=decimalCents($('.bs-journal-debit',row).value),c=decimalCents($('.bs-journal-credit',row).value);if(!(d>0&&c===0||c>0&&d===0))throw new Error('Each line requires one positive debit or credit');debit+=d;credit+=c;return {account:$('.bs-journal-account',row).value,debitCents:d,creditCents:c};});if(lines.length<2||debit!==credit)throw new Error('Enter at least two lines with equal debits and credits');await ctx.api('/api/business/admin/finance/journals',{method:'POST',body:{sourceType:'manual',sourceId:sourceId,eventType:'approved_adjustment',occurredAt:localIso($('#bs-journal-date',host).value),businessUnit:$('#bs-journal-unit',host).value,memo:checkedReason(host),lines:lines}});ctx.toast('Balanced journal posted','success');return true;}});addJournalLine();addJournalLine();}
  function reverseJournal(){ctx.modal({title:'Reverse approved manual journal',body:'<p>Use the journal ID from General Journal. A reversal creates a new balanced entry. Closed periods remain locked.</p><label class="field"><span class="label">Original journal ID</span><input class="input" id="bs-journal-reverse-id" type="number" min="1"></label>'+reasonInput(),confirmText:'Post journal reversal',onConfirm:async function(host){var id=Number($('#bs-journal-reverse-id',host).value);if(!Number.isSafeInteger(id)||id<1)throw new Error('Choose a valid journal ID');var report=await ctx.api('/api/business/admin/finance/general-journal'),entry=rows(report.rows).find(function(r){return Number(r.id)===id;});if(!entry||entry.source_type!=='manual')throw new Error('Choose a manual journal. Operational corrections use their original refund or return workflow.');await ctx.api('/api/business/admin/finance/journals/'+id+'/reverse',{method:'POST',body:{reason:checkedReason(host)}});ctx.toast('Reversal posted','success');return true;}});}
  window.PikolBusinessAdmin={install:install,load:load,loadPolicies:loadPolicies,loadFinance:loadFinance};
